//go:build bdd

// Code generated by `true-bdd build tests`. DO NOT EDIT.
//
// Source: docs/scenarios.yaml
//
// One Go test per registry scenario, with the scenario's steps stated
// literally: what a reader sees here is what the machine runs. Done
// checks these steps against the registry before running any of them,
// so a hand edit to either side fails the test rather than quietly
// making the two documents disagree.
//
// Scenarios sharing a `path:` are written here in id order, so an
// inserted scenario lands where a reader expects it instead of at the
// end. Sequential by design — the suite's harness is shared.

package bddcli_test

import (
	"testing"

	"github.com/ondatra-ai/true-bdd/tests/bdd-cli/scenarios"
)

// fix-loop-unattended-001-build-code-applies: With --fix --yes, build code --fix --yes applies every proposed fix without stdin and completes successfully
func TestFixLoopUnattended001BuildCodeApplies(t *testing.T) {
	s := scenarios.New(t, "fix-loop-unattended-001-build-code-applies")
	s.Given(`the "fix-loop-yes-build-code" project tree`)
	s.When(`the System Architect runs "build code --fix --yes"`)
	s.Then(`the command exits with code 0`)
	s.And(`stdout matches msg="Running tests" framework=go-test`)
	s.And(`stdout matches msg="Suite failures" failures=1 framework=go-test`)
	s.And(`stdout matches msg="Total failing tests across architecture" failures=1`)
	s.And(`stdout matches msg="Fix applied; re-running the failing set"`)
	s.And(`stdout matches BUILD CODE COMPLETE`)
	s.And(`the file "services/calc/calc.go" is modified`)
	s.And(`the engine spawned a test runner with arguments matching TestAddSumsItsArguments`)
	s.And(`the engine spawned exactly 3 test runners`)
	s.And(`the engine dispatched 2 AI turns`)
	s.But(`the file "tests/suite/add_test.go" is unchanged`)
	s.And(`the file "tests/suite/canary_test.go" is unchanged`)
	s.And(`the file "docs/architecture/architecture.yaml" is unchanged`)
	s.And(`the shell command "go test -json -count=1 ./tests/suite/..." run in "." exits with code 0`)
	s.And(`stdout matches Automatically applying fix`)
	s.Done()
}

// fix-loop-unattended-002-build-tests-applies: With --fix --yes, build tests --fix --yes applies every proposed fix without stdin and completes successfully
func TestFixLoopUnattended002BuildTestsApplies(t *testing.T) {
	s := scenarios.New(t, "fix-loop-unattended-002-build-tests-applies")
	s.Given(`the "fix-loop-yes-build-tests" project tree`)
	s.When(`the System Architect runs "build tests --fix --yes"`)
	s.Then(`the command exits with code 0`)
	s.And(`the file "tests/mcp/mcp_test.go" is created`)
	s.And("the file \"tests/mcp/mcp_test.go\" matches // Code generated by `true-bdd build tests`\\. DO NOT EDIT\\.")
	s.And(`the file "tests/mcp/mcp_test.go" matches scenarios\.New\(t, "INT-900"\)`)
	s.And(`exactly 1 file matching "tests/mcp/steps/*.go" is created`)
	s.And(`every step of scenario "INT-900" in "docs/scenarios.yaml" is matched by a step definition under "tests/mcp/steps"`)
	s.But(`the file "docs/scenarios.yaml" is unchanged`)
	s.And(`no file outside "tmp" and "tests" changed`)
	s.And(`stdout matches Automatically applying fix`)
	s.Done()
}

// fix-loop-unattended-003-refine-applies: With --fix --yes, us refine 96.6 --fix --yes applies every proposed fix without stdin and completes successfully
func TestFixLoopUnattended003RefineApplies(t *testing.T) {
	s := scenarios.New(t, "fix-loop-unattended-003-refine-applies")
	s.Given(`the "fix-loop-yes-us-refine" project tree`)
	s.And(`the "us-refine" checklist is narrowed to its "whether its description field contains a vague word" prompt`)
	s.When(`the Product Owner runs "us refine 96.6 --fix --yes"`)
	s.Then(`the command exits with code 0`)
	s.And(`stdout matches ALL CHECKS PASSED!`)
	s.And(`stdout matches msg="Story saved"`)
	s.And(`stdout matches REFINE COMPLETE`)
	s.And(`the only file changed outside "tmp" is "docs/product/stories/96.6-document-summary-desc-qualifier.yaml"`)
	s.And(`the story "docs/product/stories/96.6-document-summary-desc-qualifier.yaml" has id "96.6"`)
	s.And(`the story "docs/product/stories/96.6-document-summary-desc-qualifier.yaml" has 4 acceptance criteria`)
	s.And(`every acceptance criterion in the story "docs/product/stories/96.6-document-summary-desc-qualifier.yaml" has given, when and then steps`)
	s.And(`the description of acceptance criterion "AC-3" of the story "docs/product/stories/96.6-document-summary-desc-qualifier.yaml" does not match (?i)\b(properly|correctly|appropriate|user-friendly|fast|quickly|easily|seamless|intuitive)\b`)
	s.And(`stdout does not match Hit max apply attempts`)
	s.And(`stdout matches Automatically applying fix`)
	s.Done()
}

// fix-loop-unattended-004-apply-applies: With --fix --yes, us apply 99.3 --fix --yes applies every proposed fix without stdin and completes successfully
func TestFixLoopUnattended004ApplyApplies(t *testing.T) {
	s := scenarios.New(t, "fix-loop-unattended-004-apply-applies")
	s.Given(`the "fix-loop-yes-us-apply" project tree`)
	s.And(`the "us-apply" checklist is narrowed to its "already appear as a scenario in the registry" prompt`)
	s.When(`the Product Owner runs "us apply 99.3 --fix --yes"`)
	s.Then(`the command exits with code 0`)
	s.And(`stdout matches msg=AC index=1 total=2`)
	s.And(`stdout matches msg=AC index=2 total=2`)
	s.And(`stdout matches msg="RE-WALK \(fixes applied, verifying\)" attempt=2`)
	s.And(`stdout matches ALL CHECKS PASSED!`)
	s.And(`stdout matches APPLY COMPLETE`)
	s.And(`the file "docs/scenarios.yaml" is modified`)
	s.And(`exactly 1 scenario in "docs/scenarios.yaml" comes from acceptance criterion "99.3-001-mcp-initialize"`)
	s.And(`exactly 1 scenario in "docs/scenarios.yaml" comes from acceptance criterion "99.3-002-mcp-get-refused"`)
	s.And(`the scenario from acceptance criterion "99.3-001-mcp-initialize" in "docs/scenarios.yaml" is keyed "99.3-001-mcp-initialize"`)
	s.And(`the scenario from acceptance criterion "99.3-002-mcp-get-refused" in "docs/scenarios.yaml" is keyed "99.3-002-mcp-get-refused"`)
	s.And(`no two scenarios in "docs/scenarios.yaml" share the same steps`)
	s.But(`the file "docs/product/stories/99.3-rewalk-fixture.yaml" is unchanged`)
	s.And(`the only file changed outside "tmp" is "docs/scenarios.yaml"`)
	s.And(`stdout does not match msg="RE-WALK \(fixes applied, verifying\)" attempt=3`)
	s.And(`stdout does not match One or more scenarios did not pass`)
	s.And(`stdout matches Automatically applying fix`)
	s.Done()
}

// fix-loop-unattended-005-scen-check-applies: With --fix --yes, scen check --fix --yes applies every proposed fix without stdin and completes successfully
func TestFixLoopUnattended005ScenCheckApplies(t *testing.T) {
	s := scenarios.New(t, "fix-loop-unattended-005-scen-check-applies")
	s.Given(`the "fix-loop-yes-scen-check" project tree`)
	s.And(`the "scen-check" checklist is narrowed to its "whether this scenario uses each catalogue phrase" prompt`)
	s.When(`the Quality Engineer runs "scen check --fix --yes"`)
	s.Then(`the command exits with code 0`)
	s.And(`stdout matches CHECK FAILED`)
	s.And(`stdout matches FIX PROMPT GENERATED`)
	s.And(`stdout matches msg="Fix recorded in the document" document=scenarios_yaml`)
	s.And(`stdout matches ALL CHECKS PASSED`)
	s.But(`stdout does not match Hit max apply attempts`)
	s.And(`the only file changed outside "tmp" is "docs/scenarios.yaml"`)
	s.And(`the file "docs/scenarios.yaml" matches (?m)stdout matches [^\n]*Hello Ada`)
	s.And(`the engine dispatched 5 AI turns`)
	s.And(`stdout matches Automatically applying fix`)
	s.Done()
}

// fix-loop-unattended-006-clarification-yes-stops: A clarifying question under --yes prints the question and suggestions, requires a person and stops without guessing
func TestFixLoopUnattended006ClarificationYesStops(t *testing.T) {
	s := scenarios.New(t, "fix-loop-unattended-006-clarification-yes-stops")
	s.Given(`the "fix-loop-unanswered" project tree`)
	s.And(`the Quality Engineer answers "1" to every question`)
	s.When(`the Quality Engineer runs "scen check --fix --yes"`)
	s.Then(`the command exits with code 1`)
	s.And(`stdout matches What does the step "the service answers within 200 milliseconds" mean`)
	s.And(`stdout matches It means its reply arrives no later than that many milliseconds after the message was sent.`)
	s.And(`stdout matches It means the time from sending the message to its reply arriving is at most that many milliseconds.`)
	s.And(`stdout matches a person must answer`)
	s.And(`stderr matches a person must answer`)
	s.And(`stdout does not match User answered clarification question`)
	s.And(`stdout does not match SCEN CHECK COMPLETE`)
	s.And(`the engine dispatched 1 AI turn`)
	s.And(`no file outside "tmp" changed`)
	s.Done()
}

